54	                ? "STRICT" : "NORMAL";
55	        LocalDateTime now = nowUtc();
56	        try {
57	            long id = batchDao.insertBatch(request.requestId(), fingerprint, request.origin(),
58	                    request.variety(), request.batchNo(), request.quantity(),
