1	-- 农残快检与上市准入联动服务建表脚本（H2，MODE=MySQL）
2	-- 时间字段统一为 UTC 墙钟时间（TIMESTAMP，无时区），由应用以 UTC 写入。
3	
4	CREATE TABLE IF NOT EXISTS batch (
5	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
6	    request_id VARCHAR(64) NOT NULL,
7	    fingerprint VARCHAR(128) NOT NULL,
8	    origin VARCHAR(128) NOT NULL,
9	    variety VARCHAR(128) NOT NULL,
10	    batch_no VARCHAR(64) NOT NULL,
11	    quantity DECIMAL(12,2) NOT NULL,
12	    status VARCHAR(16) NOT NULL,
13	    sampling_level VARCHAR(16) NOT NULL,
14	    created_at TIMESTAMP NOT NULL,
15	    updated_at TIMESTAMP NOT NULL,
16	    CONSTRAINT uk_batch_request UNIQUE (request_id),
17	    CONSTRAINT uk_batch_biz UNIQUE (origin, variety, batch_no)
18	);
19	COMMENT ON TABLE batch IS '进场批次：产地报备创建，状态机 REPORTED/SAMPLED/FROZEN/RELEASED/DISPOSED';
20	COMMENT ON COLUMN batch.request_id IS '报备幂等请求号，全局唯一';
21	COMMENT ON COLUMN batch.fingerprint IS '幂等指纹：requestId 与全部业务字段的 SHA-256';
22	COMMENT ON COLUMN batch.origin IS '产地名称';
23	COMMENT ON COLUMN batch.variety IS '农产品品种';
24	COMMENT ON COLUMN batch.batch_no IS '批次号，与产地、品种共同唯一';
25	COMMENT ON COLUMN batch.quantity IS '进场数量（单位：吨），必填';
26	COMMENT ON COLUMN batch.status IS '批次状态：REPORTED 已报备/SAMPLED 已抽样/FROZEN 疑似冻结/RELEASED 放行（终态）/DISPOSED 处置结案（终态）';
27	COMMENT ON COLUMN batch.sampling_level IS '抽检级别：NORMAL 常规/STRICT 加严（产地预警期间报备的批次）';
28	COMMENT ON COLUMN batch.created_at IS '报备时间（UTC）';
29	COMMENT ON COLUMN batch.updated_at IS '最近状态变更时间（UTC）';
30	
31	CREATE TABLE IF NOT EXISTS sample (
32	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
33	    batch_id BIGINT NOT NULL,
34	    item VARCHAR(64) NOT NULL,
35	    created_at TIMESTAMP NOT NULL,
36	    CONSTRAINT uk_sample_batch_item UNIQUE (batch_id, item)
37	);
38	COMMENT ON TABLE sample IS '抽样记录：按批次+检测项目去重';
39	COMMENT ON COLUMN sample.batch_id IS '所属批次 ID';
40	COMMENT ON COLUMN sample.item IS '检测项目名称（如有机磷类）';
41	COMMENT ON COLUMN sample.created_at IS '抽样时间（UTC）';
42	
43	CREATE TABLE IF NOT EXISTS test_record (
44	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
45	    request_id VARCHAR(64) NOT NULL,
46	    fingerprint VARCHAR(128) NOT NULL,
47	    batch_id BIGINT NOT NULL,
48	    item VARCHAR(64) NOT NULL,
49	    inhibition_rate DECIMAL(5,2) NOT NULL,
50	    result VARCHAR(16) NOT NULL,
51	    created_at TIMESTAMP NOT NULL,
52	    CONSTRAINT uk_test_request UNIQUE (request_id),
53	    CONSTRAINT uk_test_batch_item UNIQUE (batch_id, item)
54	);
55	COMMENT ON TABLE test_record IS '快检检测记录：按批次+项目去重，重复送检拒绝';
56	COMMENT ON COLUMN test_record.request_id IS '快检幂等请求号，全局唯一';
57	COMMENT ON COLUMN test_record.fingerprint IS '幂等指纹：requestId 与全部业务字段的 SHA-256';
58	COMMENT ON COLUMN test_record.batch_id IS '所属批次 ID';
59	COMMENT ON COLUMN test_record.item IS '检测项目名称';
60	COMMENT ON COLUMN test_record.inhibition_rate IS '抑制率（单位：%），达到 50 判疑似超标（恰 50 判疑似）';
61	COMMENT ON COLUMN test_record.result IS '快检结果：NORMAL 正常/SUSPECT 疑似超标，由抑制率口径可复算';
62	COMMENT ON COLUMN test_record.created_at IS '检测时间（UTC），产地预警按 UTC 日界统计';
63	
64	CREATE TABLE IF NOT EXISTS recheck (
65	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
66	    request_id VARCHAR(64) NOT NULL,
67	    fingerprint VARCHAR(128) NOT NULL,
68	    batch_id BIGINT NOT NULL,
69	    item VARCHAR(64) NOT NULL,
70	    qualified BOOLEAN NOT NULL,
71	    created_at TIMESTAMP NOT NULL,
72	    CONSTRAINT uk_recheck_request UNIQUE (request_id),
73	    CONSTRAINT uk_recheck_batch_item UNIQUE (batch_id, item)
74	);
75	COMMENT ON TABLE recheck IS '定量复检记录：疑似冻结批次送检，合格放行、不合格转监督处置';
76	COMMENT ON COLUMN recheck.request_id IS '复检幂等请求号，全局唯一';
77	COMMENT ON COLUMN recheck.fingerprint IS '幂等指纹：requestId 与全部业务字段的 SHA-256';
78	COMMENT ON COLUMN recheck.batch_id IS '所属批次 ID';
79	COMMENT ON COLUMN recheck.item IS '复检项目名称';
80	COMMENT ON COLUMN recheck.qualified IS '复检结论：TRUE 合格/FALSE 不合格';
81	COMMENT ON COLUMN recheck.created_at IS '复检时间（UTC）';
82	
83	CREATE TABLE IF NOT EXISTS admission (
84	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
85	    batch_id BIGINT NOT NULL,
86	    released_at TIMESTAMP NOT NULL,
87	    CONSTRAINT uk_admission_batch UNIQUE (batch_id)
88	);
89	COMMENT ON TABLE admission IS '准入放行记录：与判定在同一事务内完成，每批次至多一条';
90	COMMENT ON COLUMN admission.batch_id IS '放行批次 ID';
91	COMMENT ON COLUMN admission.released_at IS '放行时间（UTC）';
92	
93	CREATE TABLE IF NOT EXISTS disposal (
94	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
95	    batch_id BIGINT NOT NULL,
96	    reason VARCHAR(255) NOT NULL,
97	    disposed_at TIMESTAMP NOT NULL,
98	    CONSTRAINT uk_disposal_batch UNIQUE (batch_id)
99	);
100	COMMENT ON TABLE disposal IS '监督处置结案记录：复检不合格转入，每批次至多一条';
101	COMMENT ON COLUMN disposal.batch_id IS '处置批次 ID';
102	COMMENT ON COLUMN disposal.reason IS '处置原因';
103	COMMENT ON COLUMN disposal.disposed_at IS '结案时间（UTC）';
104	
105	CREATE TABLE IF NOT EXISTS retention (
106	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
107	    batch_id BIGINT NOT NULL,
108	    retain_hours INT NOT NULL,
109	    retain_until TIMESTAMP NOT NULL,
110	    created_at TIMESTAMP NOT NULL,
111	    CONSTRAINT uk_retention_batch UNIQUE (batch_id)
112	);
113	COMMENT ON TABLE retention IS '留样记录：处置结案批次留样 48 小时';
114	COMMENT ON COLUMN retention.batch_id IS '留样批次 ID';
115	COMMENT ON COLUMN retention.retain_hours IS '留样时长（单位：小时），固定 48';
116	COMMENT ON COLUMN retention.retain_until IS '留样截止时间（UTC）= 结案时间 + 48 小时';
117	COMMENT ON COLUMN retention.created_at IS '留样登记时间（UTC）';
118	
119	CREATE TABLE IF NOT EXISTS origin_alert (
120	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
121	    origin VARCHAR(128) NOT NULL,
122	    variety VARCHAR(128) NOT NULL,
123	    alert_date DATE NOT NULL,
124	    trigger_count INT NOT NULL,
125	    status VARCHAR(16) NOT NULL,
126	    created_at TIMESTAMP NOT NULL,
127	    CONSTRAINT uk_alert_origin_variety_date UNIQUE (origin, variety, alert_date)
128	);
129	COMMENT ON TABLE origin_alert IS '产地预警台账：同产地同品种当日（UTC 日界）累计 3 批疑似触发，恰 3 批触发，可复算';
130	COMMENT ON COLUMN origin_alert.origin IS '产地名称';
131	COMMENT ON COLUMN origin_alert.variety IS '农产品品种';
