    @Test
    void 尚缺一项结果只能待定不得判定() throws Exception {
        FrozenCtx ctx = frozenBatch("J3");
        long jointId = createJoint("JC-3", ctx, "LAB-A", List.of("毒死蜱", "克百威"))
                .andReturnJointId();
        allocate("JA-3", jointId, 1,
